// Central image map for the customer-facing marketplace UI.
//
// Source of truth: catalogImages.json (generated by
// server/scripts/generateClientImages.mjs from
// server/scripts/catalogImages.map.json). Every distinct catalog node —
// main category, service category, subcategory and service — has its own
// unique Cloudinary asset under odforce/{main-categories,categories,
// subcategories,services}/... . Uploads are done by
// server/scripts/uploadCatalogImages.js with the server's CLOUDINARY_*
// config; the frontend never holds credentials.
//
// Lookups are deterministic and slug-based (same slugify rules as the
// server seed): callers pass the catalog names and the exact node path is
// resolved. There is NO parent fallback — a node either resolves to its own
// image or (only in case of a catalog/data mismatch) to the emergency
// default, and the mismatch is logged as [MISSING IMAGE] in dev.
import catalogImages from './catalogImages.json';

const CLOUD = 'https://res.cloudinary.com/dnn5up0tl/image/upload';
const DEFAULT_ID = catalogImages.default;

// Same slugify as server/scripts/lib/catalogNodes.mjs.
const slug = (name) =>
  String(name)
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' ')
    .replace(/['\u2019]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase();

export const imageUrl = (publicId, w = 800, h = 500) =>
  `${CLOUD}/w_${w},h_${h},c_fill,q_auto,f_auto/${publicId}`;

const devWarn = (what, detail, w = 800, h = 500) => {
  if (import.meta.env?.DEV) console.warn(`[MISSING IMAGE] ${what} -> ${detail}`);
  return imageUrl(DEFAULT_ID, w, h);
};

const suffixed = (table, suffix) => {
  const hit = Object.entries(table).find(([k]) => k.endsWith(`/${suffix}`));
  return hit ? hit[1] : null;
};

const suffixedUnique = (table, suffix) => {
  const hits = Object.entries(table).filter(([k]) => k.endsWith(`/${suffix}`));
  if (hits.length === 1) return hits[0][1];
  if (hits.length > 1) return { ambiguous: hits };
  return null;
};

// ── lookups ─────────────────────────────────────────────────────────────────

export const getMainCategoryImage = (mainCategory, w = 800, h = 500) => {
  if (!mainCategory) return devWarn('main category', 'empty', w, h);
  const hit = catalogImages.mains[slug(mainCategory)];
  return hit ? imageUrl(hit, w, h) : devWarn('main category', mainCategory, w, h);
};

// category alone is ambiguous across main categories (Hair Styling, Hair Spa,
// Facial & Skin Care exist under two mains) — pass mainCategory when known.
export const getCategoryImage = (category, mainCategory, w, h) => {
  if (!category) return devWarn('category', 'empty', w, h);
  if (mainCategory) {
    const hit = catalogImages.categories[`${slug(mainCategory)}/${slug(category)}`];
    if (hit) return imageUrl(hit, w, h);
    return devWarn('category', `${mainCategory} / ${category}`, w, h);
  }
  const hit = suffixedUnique(catalogImages.categories, slug(category));
  if (hit && typeof hit === 'string') return imageUrl(hit, w, h);
  if (hit && hit.ambiguous) return devWarn('category (ambiguous, needs mainCategory)', category, w, h);
  return devWarn('category', category, w, h);
};

export const getSubCategoryImage = (subCategory, category, mainCategory, w, h) => {
  if (!subCategory) return devWarn('subcategory', 'empty', w, h);
  if (mainCategory && category) {
    const hit =
      catalogImages.subcategories[
        `${slug(mainCategory)}/${slug(category)}/${slug(subCategory)}`
      ];
      if (hit) return imageUrl(hit, w, h);
      return devWarn('subcategory', `${mainCategory} / ${category} / ${subCategory}`, w, h);
  }
  const hit = suffixedUnique(catalogImages.subcategories, slug(subCategory));
  if (hit && typeof hit === 'string') return imageUrl(hit, w, h);
  if (hit && hit.ambiguous) {
    if (category) {
      const narrowed = hit.ambiguous.filter(([k]) => k.split('/').includes(slug(category)));
      if (narrowed.length === 1) return imageUrl(narrowed[0][1], w, h);
    }
    return devWarn('subcategory (ambiguous, needs mainCategory/category)', subCategory, w, h);
  }
  return devWarn('subcategory', subCategory, w, h);
};

// Full-path exact lookup: main/category/subcategory/service. Falls back to
// matching the service name only when the full path is unavailable (e.g. an
// older cart item), and only accepts an unambiguous match.
export const getServiceImage = (service, w, h) => {
  if (!service) return devWarn('service', 'empty', w, h);
  const { mainCategory, category, subCategory, serviceName } = service;
  if (mainCategory && category && subCategory && serviceName) {
    const hit =
      catalogImages.services[
        `${slug(mainCategory)}/${slug(category)}/${slug(subCategory)}/${slug(serviceName)}`
      ];
    if (hit) return imageUrl(hit, w, h);
  }
  if (serviceName) {
    const suffix = slug(serviceName);
    let hits = Object.entries(catalogImages.services).filter(([k]) =>
      k.endsWith(`/${suffix}`)
    );
    if (hits.length > 1 && category) {
      hits = hits.filter(([k]) => k.split('/').includes(slug(category)));
    }
    if (hits.length === 1) return imageUrl(hits[0][1], w, h);
    if (hits.length > 1) {
      return devWarn('service (ambiguous, needs full path)', serviceName, w, h);
    }
  }
  return devWarn('service', serviceName || JSON.stringify(service).slice(0, 80), w, h);
};

